//! Golden replay of upstream `qmd` CLI output — fixture generated by
//! `scripts/gen_cli_golden.ts` (`crates/qmd-cli/tests/fixtures/
//! cli_golden.json`, upstream tobi/qmd v2.8.3). Each group is rebuilt
//! byte-for-byte: corpus files with pinned mtimes, root-relative
//! `extra_files`, the recorded `config_yaml` (written to the global
//! config dir or — for a `local_config` group — inside
//! `corpus/.qmd/`), and the index populated through the *library*
//! `Qmd::update` so replaying a mutating scenario starts from the
//! same index state upstream captured.
//!
//! Scenarios run as a `CARGO_BIN_EXE_qmd` subprocess under the same
//! isolation the generator used (explicit minimal env, `NO_COLOR=1`,
//! `TZ=UTC`, plus per-scenario `env` overrides). `check` semantics:
//! `exact` compares stdout+stderr+exit; `stdout-exit` also pins the
//! first stderr line's `Invalid --filter JSON: ` prefix and the second
//! line verbatim (the engine message in between cannot match — design
//! P4.1 §5 note 4); `normalized` applies the generator's
//! `softNormalize` to our captured output before comparing; `record` is
//! skipped. `pre` runs a silent scenario first; `write`/`delete`
//! mutate the corpus before the run; `links` creates root-relative
//! symlinks; `state` asserts post-run files (`link` compares the
//! symlink target when the entry is one).
//!
//! The `mutate`, `local` and `init` groups exercise the P4.2 commands
//! (`update`, `collection`, `context`, `status`, `trust`, `init`,
//! `cleanup`) end to end: config mutation is asserted through `state`
//! snapshots and trust records through `config/trusted.json`.
//!
//! Every non-`record` scenario is compared; the test asserts the
//! compared count equals the fixture's non-record total so a filtering
//! bug can never silently skip scenarios.

#![allow(
    unused_crate_dependencies,
    reason = "each test binary only uses a subset of the package deps"
)]
#![allow(
    clippy::tests_outside_test_module,
    clippy::shadow_unrelated,
    clippy::indexing_slicing,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::missing_assert_message,
    clippy::panic,
    clippy::print_stdout,
    clippy::print_stderr,
    reason = "idiomatic test-code patterns; mismatches are reported on stderr"
)]

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, UNIX_EPOCH};

use qmd::{Environment, Qmd, UpdateOptions};
use regex::Regex;
use serde_json::Value;

const BIN: &str = env!("CARGO_BIN_EXE_qmd");
const FIXTURE: &str = include_str!("fixtures/cli_golden.json");

/// `record` scenarios that get sanity assertions (upstream's help and
/// version text differs by design — P4-D2/D8 — so only shape is pinned).
fn sanity_scenario(name: &str) -> bool {
    matches!(name, "no args" | "--help" | "--version")
}

fn cwd_of(root: &Path, corpus: &Path, outside: &Path, cwd: &str) -> PathBuf {
    match cwd {
        "corpus" => corpus.to_path_buf(),
        "docs" => corpus.join("docs"),
        "root" => root.to_path_buf(),
        "outside" => outside.to_path_buf(),
        // `proj_dir` groups get an empty `<root>/proj` — the `init`
        // scenarios' working directory.
        "proj" => root.join("proj"),
        other => panic!("unknown cwd {other}"),
    }
}

/// Minimal subprocess environment, mirroring the generator's `env`.
/// Per-scenario `env` entries override the defaults; `<PROJ>` values
/// become `<root>/proj` like the generator's substitution.
fn scenario_env(
    root: &Path,
    home: &Path,
    cwd: &Path,
    index_path: bool,
    scenario: &Value,
) -> Vec<(String, String)> {
    let mut env = vec![
        ("PATH".to_owned(), "/usr/bin:/bin".to_owned()),
        ("HOME".to_owned(), home.to_string_lossy().into_owned()),
        (
            "XDG_CONFIG_HOME".to_owned(),
            root.join("xdg-config").to_string_lossy().into_owned(),
        ),
        (
            "XDG_CACHE_HOME".to_owned(),
            root.join("xdg-cache").to_string_lossy().into_owned(),
        ),
        (
            "QMD_CONFIG_DIR".to_owned(),
            root.join("config").to_string_lossy().into_owned(),
        ),
        ("TZ".to_owned(), "UTC".to_owned()),
        ("NO_COLOR".to_owned(), "1".to_owned()),
        ("QMD_DOCTOR_DEVICE_PROBE".to_owned(), "0".to_owned()),
        (
            "TMPDIR".to_owned(),
            root.join("tmp").to_string_lossy().into_owned(),
        ),
        ("PWD".to_owned(), cwd.to_string_lossy().into_owned()),
    ];
    if index_path {
        env.push((
            "INDEX_PATH".to_owned(),
            root.join("index.sqlite").to_string_lossy().into_owned(),
        ));
    }
    if let Some(overrides) = scenario["env"].as_object() {
        let proj = root.join("proj");
        for (key, value) in overrides {
            // The generator substitutes whole-value `<PROJ>` and `<ROOT>`
            // in-place (e.g. `QMD_SKILLS_DIR: "<ROOT>/fskills"`).
            let value = value.as_str().unwrap();
            let value = if value == "<PROJ>" {
                proj.to_string_lossy().into_owned()
            } else {
                value.replace("<ROOT>", &root.to_string_lossy())
            };
            env.retain(|(k, _)| k != key);
            env.push((key.clone(), value));
        }
    }
    env
}

/// The `Environment` the setup `Qmd` handle gets — same values the
/// subprocess env passes.
fn setup_env(root: &Path, home: &Path, index_path: bool) -> Environment {
    let mut env = Environment::default();
    env.home = Some(home.to_path_buf());
    env.xdg_config_home = Some(root.join("xdg-config"));
    env.xdg_cache_home = Some(root.join("xdg-cache"));
    env.qmd_config_dir = Some(root.join("config"));
    if index_path {
        env.index_path = Some(root.join("index.sqlite"));
    }
    env
}

/// Database path matching the scenario env (`INDEX_PATH` or the named
/// index under `XDG_CACHE_HOME`).
fn db_path(env: &Environment, index_name: &str) -> PathBuf {
    qmd::paths::default_db_path(env, index_name)
}

/// Sanity assertions for `record` scenarios (upstream help/version
/// text differs by design — P4-D2/D8 — so only the shape is pinned).
fn sanity_check(name: &str, exit_code: i32, stdout: &str) -> Option<String> {
    let ok = match name {
        "no args" => exit_code == 1 && stdout.contains("Usage:") && stdout.contains("--no-gpu"),
        "--help" => exit_code == 0 && stdout.contains("Usage:") && stdout.contains("--no-gpu"),
        "--version" => exit_code == 0 && stdout.starts_with("qmd "),
        _ => return None,
    };
    (!ok).then(|| format!("{name}: sanity failed: exit {exit_code}, stdout {stdout:?}"))
}

/// `record` scenarios that also run under sanity assertions.
fn sanity_scenario_total(fixture: &Value) -> usize {
    fixture["groups"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|g| g["scenarios"].as_array().unwrap().iter())
        .filter(|s| {
            s["check"].as_str().unwrap() == "record" && sanity_scenario(s["name"].as_str().unwrap())
        })
        .count()
}

/// The generator's `softNormalize` — the same regex substitutions, in
/// the same order, applied to our captured output for `normalized`
/// scenarios and to every `state` file's contents (postState is always
/// soft-normalized upstream). One addition beyond the generator's set:
/// the `trusted.json` hooks digest hashes the collection paths, so the
/// recorded `<ROOT>`-dependent value can never match ours — it
/// normalizes to `<HOOKS>` on both sides.
fn soft_normalize(s: &str) -> String {
    let s = Regex::new(r"\d+[smhd] ago")
        .unwrap()
        .replace_all(s, "<AGO>");
    // `(\n|^)(\s*)Size:.*(\n|$)` — preserve the leading whitespace block.
    let s = Regex::new(r"(\n|^)(\s*)Size:.*(\n|$)")
        .unwrap()
        .replace_all(&s, "${1}${2}Size: <SIZE>${3}");
    let s = Regex::new(r"trusted \d{4}-\d{2}-\d{2}T[^\s)]*")
        .unwrap()
        .replace_all(&s, "trusted <TS>");
    let s = Regex::new(r#""trustedAt": "[^"]*""#)
        .unwrap()
        .replace_all(&s, "\"trustedAt\": \"<TS>\"");
    let s = Regex::new(r"(?m)^  Status:.*$")
        .unwrap()
        .replace_all(&s, "  Status: <AST>");
    let s = Regex::new(r"(?m)^  Languages:.*\n")
        .unwrap()
        .replace_all(&s, "");
    let s = Regex::new(r"(?m)^  Unavailable:.*\n")
        .unwrap()
        .replace_all(&s, "");
    // P4.3 doctor tokens — driver/version differences between Bun's
    // bundled libs and rusqlite (generator comments at softNormalize).
    let s = Regex::new(r"(?m)^Runtime:.*$")
        .unwrap()
        .replace_all(&s, "Runtime: <DRIVER>");
    let s = Regex::new(r"(?m)SQLite runtime:.*$")
        .unwrap()
        .replace_all(&s, "SQLite runtime: <VER>");
    let s = Regex::new(r"(?m)better-sqlite3 package:.*$")
        .unwrap()
        .replace_all(&s, "better-sqlite3 package: <PKG>");
    let s = Regex::new(r"(?m)sqlite-vec:.*$")
        .unwrap()
        .replace_all(&s, "sqlite-vec: <VER>");
    // The trust digest hashes absolute paths — `<ROOT>`-dependent.
    let s = Regex::new(r#""hooks": "[0-9a-f]{64}""#)
        .unwrap()
        .replace_all(&s, "\"hooks\": \"<HOOKS>\"");
    // P4.4: the port does not ship upstream's `release` skill (P4-D7 —
    // maintainer-only). Fold its `skills list` row and `--json` data
    // entry out like the generator does.
    let s = Regex::new(r"(?m)^  release  .*\n")
        .unwrap()
        .replace_all(&s, "");
    let s = Regex::new(r#",\{"name":"release","description":"(?:[^"\\]|\\.)*"\}"#)
        .unwrap()
        .replace_all(&s, "");
    // Upstream's `qmd` row was `padEnd(7)` for `release`; ours pads to
    // its own max — fold the gap like the generator.
    Regex::new(r"(?m)^  qmd {2,}")
        .unwrap()
        .replace_all(&s, "  qmd  ")
        .into_owned()
}

/// One prepared fixture group: directories, corpus, config and the
/// index populated through the library (`update` CLI is P4.2).
struct Group {
    /// `<top>/<name>` — the `<ROOT>` placeholder target.
    root: PathBuf,
    /// `<root>/corpus`.
    corpus: PathBuf,
    /// Whether the group sets `INDEX_PATH`.
    index_path: bool,
}

/// Write a fixture file entry (`path`, `content`, pinned `mtime`)
/// relative to `base`.
fn write_fixture_file(base: &Path, file: &Value) {
    let path = base.join(file["path"].as_str().unwrap());
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(&path, file["content"].as_str().unwrap()).unwrap();
    let mtime = UNIX_EPOCH + Duration::from_secs(file["mtime"].as_u64().unwrap());
    fs::File::options()
        .write(true)
        .open(&path)
        .unwrap()
        .set_modified(mtime)
        .unwrap();
}

fn setup_group(group: &Value, top: &Path, home: &Path) -> Group {
    let root = top.join(group["name"].as_str().unwrap());
    let corpus = root.join("corpus");
    let proj = root.join("proj");
    for dir in [
        corpus.clone(),
        root.join("config"),
        root.join("tmp"),
        root.join("xdg-config"),
        root.join("xdg-cache"),
    ] {
        fs::create_dir_all(&dir).unwrap();
    }
    // `proj_dir`: the empty directory `qmd init` runs inside.
    if group["proj_dir"].as_bool().unwrap_or(false) {
        fs::create_dir_all(&proj).unwrap();
    }
    for file in group["files"].as_array().unwrap() {
        write_fixture_file(&corpus, file);
    }
    // `extra_files` live outside the corpus (e.g. `external/ext.md`,
    // the out-of-project collection's content), still `<root>`-relative.
    for file in group["extra_files"]
        .as_array()
        .map_or(&[][..], Vec::as_slice)
    {
        write_fixture_file(&root, file);
    }

    // A `local_config` group has no global config: `config_yaml` is
    // written inside the corpus at the recorded path (with `<ROOT>`
    // detokenized), matching upstream's checked-in `.qmd/index.yaml`.
    let config_yaml = group["config_yaml"]
        .as_str()
        .unwrap()
        .replace("<ROOT>", &root.to_string_lossy());
    let local_config = group["local_config"].as_str();
    let config_path = local_config.map_or_else(
        || {
            let p = root
                .join("config")
                .join(group["config_name"].as_str().unwrap());
            fs::write(&p, &config_yaml).unwrap();
            p
        },
        |rel| {
            let p = root.join(rel);
            fs::create_dir_all(p.parent().unwrap()).unwrap();
            fs::write(&p, &config_yaml).unwrap();
            p
        },
    );

    let index_name = group["index_name"].as_str().unwrap_or("index").to_owned();
    let index_path = group["index_path"].as_bool().unwrap();
    if !group["no_setup"].as_bool().unwrap_or(false) {
        let env = setup_env(&root, home, index_path);
        // A `local_config` index lives at `.qmd/index-rs.sqlite` (the
        // `local_db_path` convention); global groups keep `INDEX_PATH`.
        let db = match local_config {
            Some(_) => qmd::paths::local_db_path(&config_path),
            None => db_path(&env, &index_name),
        };
        let qmd = Qmd::builder(db)
            .environment(env.clone())
            .config_file(&config_path)
            .build()
            .unwrap();
        // `getStore` runs `ensureModelsConfiguredForCli` on every open
        // — the setup update pins `models:` into the config the same
        // way upstream's `update` did (the recorded `state` expects it).
        let _resolved = qmd.ensure_models_configured();
        // Upstream's setup `update` ran untrusted for a local config:
        // collections whose path gates (outside the project) are
        // skipped while in-project ones index (cli/qmd.ts:942-946).
        // Reproduce that post-state through the collection filter.
        let collections = local_config.map(|_| {
            let config = qmd::config::load(&config_path).unwrap();
            let snapshot = qmd::trust::collect_sensitive_snapshot(&config);
            let gated = qmd::trust::local_config_gated(&config_path, &snapshot, &env);
            let skipped: Vec<&str> = gated.paths.iter().map(|p| p.collection.as_str()).collect();
            config
                .collections
                .keys()
                .filter(|n| !skipped.contains(&n.as_str()))
                .cloned()
                .collect::<Vec<_>>()
        });
        match collections {
            // Every collection is gated — upstream indexed nothing.
            Some(keep) if keep.is_empty() => {}
            keep => {
                qmd.update(&UpdateOptions { collections: keep }, &mut |_| {})
                    .unwrap();
            }
        }
        drop(qmd);
    }
    for rel in group["delete_after_setup"].as_array().unwrap() {
        fs::remove_file(corpus.join(rel.as_str().unwrap())).unwrap();
    }
    Group {
        root,
        corpus,
        index_path,
    }
}

/// Spawn the `qmd` binary with the scenario env.
fn run_qmd(argv: &[String], cwd: &Path, env: &[(String, String)]) -> std::process::Output {
    Command::new(BIN)
        .args(argv)
        .current_dir(cwd)
        .env_clear()
        .envs(env.iter().cloned())
        .stdin(Stdio::null())
        .output()
        .unwrap()
}

/// Apply a scenario's `write`/`delete` corpus mutations (`write`
/// contents are verbatim, both are corpus-relative) and create the
/// root-relative `links` symlinks (P4.4 skills scenarios).
fn apply_mutations(root: &Path, corpus: &Path, scenario: &Value) {
    if let Some(map) = scenario["write"].as_object() {
        for (rel, content) in map {
            let path = corpus.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, content.as_str().unwrap()).unwrap();
        }
    }
    for rel in scenario["delete"].as_array().map_or(&[][..], Vec::as_slice) {
        fs::remove_file(corpus.join(rel.as_str().unwrap())).unwrap();
    }
    for link in scenario["links"].as_array().map_or(&[][..], Vec::as_slice) {
        let path = root.join(link["path"].as_str().unwrap());
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::os::unix::fs::symlink(link["target"].as_str().unwrap(), &path).unwrap();
    }
}

/// Post-run `state` assertions (`<root>`-relative paths, contents
/// compared after the same normalize + softNormalize the generator
/// applied — idempotent, so re-normalizing the recorded side is safe)
/// — the problem lines, empty when all hold.
fn state_problems(
    id: &str,
    root: &Path,
    scenario: &Value,
    normalize: &dyn Fn(&str) -> String,
) -> Vec<String> {
    let mut problems = Vec::new();
    for st in scenario["state"].as_array().map_or(&[][..], Vec::as_slice) {
        let rel = st["path"].as_str().unwrap();
        let path = root.join(rel);
        // A `link` entry pins the symlink target verbatim — it is a
        // relative path (`.claude/skills/qmd` → `../../.agents/...`).
        if let Some(want_link) = st["link"].as_str() {
            match fs::read_link(&path) {
                Ok(got) if got.to_string_lossy() == want_link => continue,
                other => problems.push(format!("state {rel}: link {want_link:?}, got {other:?}")),
            }
            continue;
        }
        if st["exists"].as_bool().unwrap() {
            let got = soft_normalize(&normalize(
                &fs::read_to_string(&path).unwrap_or_else(|e| panic!("{id}: state {rel}: {e}")),
            ));
            let want = soft_normalize(st["content"].as_str().unwrap());
            if got != want {
                problems.push(diff(&format!("state {rel}"), &want, &got));
            }
        } else if path.exists() {
            problems.push(format!("state {rel}: expected absent"));
        }
    }
    problems
}

#[test]
fn cli_golden_replay() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    let top = tempfile::tempdir().unwrap();
    // macOS /tmp is /private/tmp — upstream prints realpaths.
    let top = top.path().canonicalize().unwrap();
    let home = top.join("home");
    let outside = top.join("outside");
    fs::create_dir_all(&home).unwrap();
    fs::create_dir_all(&outside).unwrap();

    let mut compared = 0usize;
    let mut mismatches: Vec<String> = Vec::new();

    for group in fixture["groups"].as_array().unwrap() {
        let Group {
            root,
            corpus,
            index_path,
        } = setup_group(group, &top, &home);

        // `-rs.sqlite` folds our deliberate `-rs` db-name deviation
        // back to upstream's name (`qmd.rs::init_local` documents it);
        // the recorded side keeps the literal `index.sqlite`.
        let normalize = |s: &str| -> String {
            s.replace(&*root.to_string_lossy(), "<ROOT>")
                .replace(&*home.to_string_lossy(), "<HOME>")
                .replace("-rs.sqlite", ".sqlite")
        };

        for scenario in group["scenarios"].as_array().unwrap() {
            let name = scenario["name"].as_str().unwrap();
            let argv: Vec<String> = scenario["argv"]
                .as_array()
                .unwrap()
                .iter()
                .map(|a| a.as_str().unwrap().to_owned())
                .collect();
            let check = scenario["check"].as_str().unwrap();
            let cwd = cwd_of(&root, &corpus, &outside, scenario["cwd"].as_str().unwrap());

            if check == "record" && !sanity_scenario(name) {
                continue;
            }

            apply_mutations(&root, &corpus, scenario);

            let env = scenario_env(&root, &home, &cwd, index_path, scenario);
            // `pre`: a preparatory command (e.g. `collection update-cmd`)
            // whose output is not part of the assertion — run silently.
            if let Some(pre) = scenario["pre"].as_array() {
                let pre_argv: Vec<String> =
                    pre.iter().map(|a| a.as_str().unwrap().to_owned()).collect();
                run_qmd(&pre_argv, &cwd, &env);
            }

            let output = run_qmd(&argv, &cwd, &env);
            let mut stdout = normalize(&String::from_utf8_lossy(&output.stdout));
            let mut stderr = normalize(&String::from_utf8_lossy(&output.stderr));
            // `normalized`: the fixture text was soft-normalized at
            // generation time, so ours must be too.
            if check == "normalized" {
                stdout = soft_normalize(&stdout);
                stderr = soft_normalize(&stderr);
            }
            let exit_code = output.status.code().unwrap_or(-1);
            compared += 1;

            if check == "record" {
                mismatches.extend(sanity_check(name, exit_code, &stdout));
                continue;
            }

            let want_stdout = scenario["stdout"].as_str().unwrap();
            let want_stderr = scenario["stderr"].as_str().unwrap();
            let want_exit = i32::try_from(scenario["exit_code"].as_i64().unwrap()).unwrap();
            let id = format!(
                "{}/{name} ({})",
                group["name"].as_str().unwrap(),
                argv.join(" ")
            );

            let mut problems: Vec<String> = Vec::new();
            if stdout != want_stdout {
                problems.push(diff("stdout", want_stdout, &stdout));
            }
            let stderr_ok = if check == "stdout-exit" {
                // The first line embeds JS-engine text that cannot match;
                // pin the prefix and the second line verbatim (design §5.4).
                let (got1, got_rest) = stderr.split_once('\n').unwrap_or((&stderr, ""));
                let want_rest = want_stderr.split_once('\n').map_or("", |(_, r)| r);
                got1.starts_with("Invalid --filter JSON: ") && got_rest == want_rest
            } else {
                stderr == want_stderr
            };
            if !stderr_ok {
                problems.push(diff("stderr", want_stderr, &stderr));
            }
            if exit_code != want_exit {
                problems.push(format!("exit: want {want_exit}, got {exit_code}"));
            }
            problems.extend(state_problems(&id, &root, scenario, &normalize));
            if !problems.is_empty() {
                mismatches.push(format!("=== {id}\n{}", problems.join("\n")));
            }
        }
    }

    let total = fixture["groups"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|g| g["scenarios"].as_array().unwrap().iter())
        .filter(|s| s["check"].as_str().unwrap() != "record")
        .count()
        + sanity_scenario_total(&fixture);
    eprintln!("cli_golden_replay: {compared} compared");
    assert_eq!(
        compared, total,
        "every non-record scenario (plus the record sanity cases) must be compared"
    );
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{}",
        mismatches.len(),
        mismatches.join("\n\n")
    );
}

/// First differing line plus a couple of lines of context, both sides.
fn diff(label: &str, want: &str, got: &str) -> String {
    if want == got {
        return String::new();
    }
    let want_lines: Vec<&str> = want.split('\n').collect();
    let got_lines: Vec<&str> = got.split('\n').collect();
    let i = (0..want_lines.len().max(got_lines.len()))
        .find(|&i| want_lines.get(i) != got_lines.get(i))
        .unwrap_or(0);
    let start = i.saturating_sub(2);
    let render = |lines: &[&str]| -> String {
        (start..(i + 3).min(lines.len()))
            .map(|j| format!("  {j}: {:?}", lines[j]))
            .collect::<Vec<_>>()
            .join("\n")
    };
    format!(
        "{label}: first diff at line {i}\n want:\n{}\n got:\n{}",
        render(&want_lines),
        render(&got_lines)
    )
}
